import concurrent.futures, json, os, urllib.request, urllib.error
from pathlib import Path
root=Path(os.environ['STAMPED_JUDGE_TARGET'])
src=json.loads((root/'input/sources.json').read_text())
urls=[]
urls.append(('cohort_table',src['cohort_source']['url']))
for name,row in src['files'].items(): urls.append((name,row['url']))
def check(pair):
 label,url=pair
 req=urllib.request.Request(url,method='HEAD',headers={'User-Agent':'independent-assessment-access-check/1.0'})
 try:
  with urllib.request.urlopen(req,timeout=15) as r: return {'artifact':label,'url':url,'status':r.status,'final_url':r.geturl(),'content_length':r.headers.get('Content-Length')}
 except Exception as e: return {'artifact':label,'url':url,'error':type(e).__name__+': '+str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool: rows=list(pool.map(check,urls))
print(json.dumps({'scope':'HEAD-only check of source URLs declared in input/sources.json; not a retrieval check of the complete project or environment','checked':len(rows),'reachable':sum('status' in r and 200<=r['status']<400 for r in rows),'failures':[r for r in rows if 'status' not in r or not 200<=r['status']<400],'results':rows},indent=2))
