const r = await tools.exec_command({cmd:"cat > "$STAMPED_JUDGE_OUTPUT/manifest_check.py" <<'PY'
import json, os, hashlib
from pathlib import Path
m_path=Path(os.environ['STAMPED_DELIVERY_MANIFEST']); root=Path(os.environ['STAMPED_JUDGE_TARGET'])
m=json.loads(m_path.read_text()); ptr=json.loads((root.parent.parent/'judge-target.json').read_text())
expected=[e for e in m['entries'] if e['path'].startswith('content/workspace/')]
missing=[]; mismatches=[]; type_errors=[]; checked=0
for e in expected:
 rel=e['path'][len('content/workspace/'):]; p=root/rel
 if not p.exists() and not p.is_symlink(): missing.append(rel); continue
 if e['kind']=='symlink':
  if not p.is_symlink(): type_errors.append((rel,'expected symlink'))
  elif os.readlink(p)!=e.get('link_target'): mismatches.append((rel,'link target',os.readlink(p),e.get('link_target')))
  elif hashlib.sha256(os.fsencode(os.readlink(p))).hexdigest()!=e['sha256']: mismatches.append((rel,'symlink hash'))
 elif e['kind']=='file':
  if p.is_symlink() or not p.is_file(): type_errors.append((rel,'expected regular file'))
  elif 'sha256' in e:
   checked+=1
   if hashlib.sha256(p.read_bytes()).hexdigest()!=e['sha256']: mismatches.append((rel,'file hash'))
 elif e['kind']=='directory' and not p.is_dir(): type_errors.append((rel,'expected directory'))
actual={str(p.relative_to(root)) for p in root.rglob('*')}
expected_paths={e['path'][len('content/workspace/'):] for e in expected}
result={'capture_status':m['capture_status'],'manifest_sha256':hashlib.sha256(m_path.read_bytes()).hexdigest(),'pointer_manifest_sha256':ptr['capture']['sha256'],'pointer_reference_limits':ptr.get('reference_limits'),'manifest_workspace_entries':len(expected),'regular_file_hashes_checked':checked,'missing':missing,'mismatches':mismatches,'type_errors':type_errors,'extra_workspace_paths':sorted(actual-expected_paths),'non_workspace_manifest_entries':len(m['entries'])-len(expected),'external_capture_omissions_or_errors':m.get('errors',[])+m.get('omissions',[])}
print(json.dumps(result,indent=2))
